      function draw(root, series, chart){ const W=920,H=470,m={t:30,r:54,b:42,l:50}, iw=W-m.l-m.r, ih=H-m.t-m.b, pts=series.flatMap(s=>s.points); if(!pts.length){root.textContent="Waiting for data";return;} const tx=domain(pts.map(p=>p.time)), left=series.filter(s=>s.axis!=="right").flatMap(s=>s.points.map(p=>p.value)), right=series.filter(s=>s.axis==="right").flatMap(s=>s.points.map(p=>p.value)); const ly=chart.fixedDomains?.left||domain(left.length?left:right); let ry=chart.fixedDomains?.right||(right.length?domain(right):ly); if(shouldForceZeroLeftAxis(chart)){ ly.min=Math.min(ly.min,0); ly.max=Math.max(ly.max,0); } if(ly.min===ly.max) ly.max=ly.min+1; if(right.length&&ry.min===ry.max) ry.max=ry.min+1; if(chart.axisDirection==="inverted"&&!chart.fixedDomains?.right) ry={min:ry.max,max:ry.min}; const sx=t=>m.l+(t-tx.min)/(tx.max-tx.min)*iw, sy=(v,a)=>{const d=a==="right"?ry:ly; return m.t+(1-(v-d.min)/(d.max-d.min))*ih}, leftTicks=ticks(ly,5), showZeroLine=ly.min<=0&&ly.max>=0, showZeroLabel=showZeroLine&&!leftTicks.some(t=>Math.abs(t)<=1e-9), maxGap=chart.id==="ge_ifo_price_expectations"?62*24*60*60*1000:Infinity; let svg='<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+chart.title+'"><defs><clipPath id="'+chart.id+'-plot-clip"><rect x="'+m.l+'" y="'+m.t+'" width="'+iw+'" height="'+ih+'"/></clipPath></defs>'; leftTicks.forEach(t=>{const y=sy(t,"left"); svg+='<line class="grid-line" x1="'+m.l+'" x2="'+(W-m.r)+'" y1="'+y+'" y2="'+y+'"/><text class="tick '+(chart.id==="sentix_pmi"?"sentix-pmi-left-tick":"")+'" text-anchor="end" x="'+(m.l-10)+'" y="'+(y+4)+'">'+fmtForChart(t,chart)+'</text>';}); if(right.length) ticks(ry,5).forEach(t=>{const y=sy(t,"right"); svg+='<text class="tick '+(chart.id==="sentix_pmi"?"sentix-pmi-right-tick":"")+'" text-anchor="start" x="'+(W-m.r+10)+'" y="'+(y+4)+'">'+fmtForChart(t,chart)+'</text>';}); ticks(tx,7).forEach(t=>{const x=sx(t); svg+='<line class="grid-line" x1="'+x+'" x2="'+x+'" y1="'+m.t+'" y2="'+(H-m.b)+'"/><text class="tick" text-anchor="middle" x="'+x+'" y="'+(H-m.b+24)+'">'+new Date(t).getFullYear().toString().slice(2)+'</text>';}); if(showZeroLine){ const zeroY=sy(0,"left"); svg+='<line class="axis-line" x1="'+m.l+'" x2="'+(W-m.r)+'" y1="'+zeroY+'" y2="'+zeroY+'"/>'; if(showZeroLabel) svg+='<text class="tick '+(chart.id==="sentix_pmi"?"sentix-pmi-left-tick":"")+'" text-anchor="end" x="'+(m.l-10)+'" y="'+(zeroY+4)+'">'+fmtForChart(0,chart)+'</text>'; } svg+='<line class="axis-line" x1="'+m.l+'" x2="'+m.l+'" y1="'+m.t+'" y2="'+(H-m.b)+'"/><line class="axis-line" x1="'+m.l+'" x2="'+(W-m.r)+'" y1="'+(H-m.b)+'" y2="'+(H-m.b)+'"/>'; if(chart.yRight) svg+='<line class="axis-line" x1="'+(W-m.r)+'" x2="'+(W-m.r)+'" y1="'+m.t+'" y2="'+(H-m.b)+'"/>'; svg+='<text class="tick" x="'+m.l+'" y="20">'+chart.yLeft+'</text>'; if(chart.yRight) svg+='<text class="tick '+(chart.id==="sentix_pmi"?"sentix-pmi-right-tick":"")+'" text-anchor="end" x="'+(W-m.r)+'" y="20">'+chart.yRight+'</text>'; series.forEach(s=>{ if(s.bar){ const base=sy(ry.min,"right"), bw=Math.max(1.5,Math.min(8,iw/Math.max(s.points.length,1)*.8)); s.points.forEach(p=>{ const y=sy(p.value,s.axis); svg+='<rect clip-path="url(#'+chart.id+'-plot-clip)" fill="'+s.color+'" fill-opacity=".8" x="'+(sx(p.time)-bw/2).toFixed(2)+'" y="'+y.toFixed(2)+'" width="'+bw.toFixed(2)+'" height="'+Math.max(0,base-y).toFixed(2)+'"/>'; }); } else if(s.id.endsWith("_daily")){ s.points.forEach(p=>{ svg+='<circle class="point" clip-path="url(#'+chart.id+'-plot-clip)" fill="'+s.color+'" cx="'+sx(p.time).toFixed(2)+'" cy="'+sy(p.value,s.axis).toFixed(2)+'" r="2.2"/>'; }); } else { svg+='<path class="line" clip-path="url(#'+chart.id+'-plot-clip)" stroke="'+s.color+'" '+(s.dashArray?'stroke-dasharray="'+s.dashArray+'" ':'')+'d="'+s.points.map((p,i)=>(i===0||p.time-s.points[i-1].time>maxGap?'M':'L')+sx(p.time).toFixed(2)+','+sy(p.value,s.axis).toFixed(2)).join(' ')+'"/>'; } }); root.innerHTML=svg+'</svg><div class="chart-tooltip" hidden></div>'; const tip=root.querySelector('.chart-tooltip'), svgEl=root.querySelector('svg'); svgEl.addEventListener('mouseleave',()=>{tip.hidden=true}); svgEl.addEventListener('mousemove',ev=>{ const rect=svgEl.getBoundingClientRect(), x=(ev.clientX-rect.left)/rect.width*W, y=(ev.clientY-rect.top)/rect.height*H; if(x<m.l||x>W-m.r||y<m.t||y>H-m.b){tip.hidden=true;return;} const target=tx.min+(x-m.l)/iw*(tx.max-tx.min); const nearest=series.map(s=>{ const p=s.points.reduce((a,b)=>Math.abs(b.time-target)<Math.abs(a.time-target)?b:a); return {s,p,x:sx(p.time),y:sy(p.value,s.axis)}; }); const anchor=nearest.reduce((a,b)=>Math.abs(b.p.time-target)<Math.abs(a.p.time-target)?b:a); tip.innerHTML='<div class="tooltip-date">'+dateLabel(anchor.p.date,chart.id)+'</div>'+nearest.map(n=>'<div class="tooltip-row"><span class="swatch" style="background:'+n.s.color+'"></span><span>'+n.s.name+'</span><strong>'+fmtForChart(n.p.value,chart)+'</strong></div>').join(''); tip.style.left=(anchor.x/W*100)+'%'; tip.style.top=(Math.min(...nearest.map(n=>n.y))/H*100)+'%'; tip.hidden=false; }); }
      function titleCase(v){ return String(v||"").split(/\s+/).filter(Boolean).map(w=>w.charAt(0).toUpperCase()+w.slice(1).toLowerCase()).join(" "); }
      function domain(v){ let min=Math.min(...v), max=Math.max(...v); if(min===max){min-=1;max+=1;} const p=(max-min)*.12; return {min:min-p,max:max+p}; }
