      function fmt(v){ const a=Math.abs(v), d=a>=100?0:a>=10?1:2; return v.toLocaleString("en-US",{minimumFractionDigits:d,maximumFractionDigits:d}); }
      function fmtFixed2(v){ return v.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2}); }
      function fmtForChart(v,chart){ return chart.tab==="inflation"||chart.tab==="country-inflation"?fmtFixed2(v):fmt(v); }
      function fmtCell(v){ return Number.isFinite(v) ? fmtFixed2(v) : ""; }
      function fmtChange(v){ return Number.isFinite(v) ? (v>0?"+":"")+fmtFixed2(v) : ""; }
      function heatStyle(v,values){ if(!Number.isFinite(v)) return ""; const nums=values.filter(Number.isFinite), max=Math.max(...nums.map(x=>Math.abs(x)))||1, intensity=Math.min(Math.abs(v)/max,1), color=v>=0?"168,63,57":"17,103,95", text=v>=0?"#7f2f2a":"#0f5f58"; return "background:rgba("+color+","+(0.1+intensity*0.24).toFixed(3)+");color:"+text+";font-weight:720"; }
      function dateLabel(date,chartId){ return new Intl.DateTimeFormat(chartId==="weekly_activity"?"en-GB":"en-US",chartId==="weekly_activity"?{day:"2-digit",month:"2-digit",year:"numeric"}:{month:"2-digit",year:"numeric"}).format(new Date(date+"T00:00:00")); }
