      function chartLastUpdate(series,chart){ if(chart.chartType==="seasonality"){ const current=series.filter(s=>/_2026$/.test(s.id)).flatMap(s=>s.points||[]); if(!current.length) return ""; const idx=Math.max(...current.map(p=>seasonalIndex(p.date))); return idx===0?"Dec/25":seasonalityLabels[idx]+"/26"; } const points=series.flatMap(s=>s.points||[]).filter(p=>p.date&&Number.isFinite(p.time)); if(!points.length) return ""; const latest=points.reduce((a,b)=>b.time>a.time?b:a); return monthYearLabel(latest.date); }
